// Generates src/init/build_config.ts with the VSX gallery URL baked in.
// Usage:
//   node scripts/set-vsx-gallery.mjs                          → empty (external release)
//   node scripts/set-vsx-gallery.mjs https://proxy.example.com/gallery  → baked in (internal)
//
// Every script that compiles or type-checks `src/` must run this first: the
// generated file is gitignored, so a fresh clone has none and `tsc` fails on
// the import in src/init/vsix.ts.
import { writeFileSync } from "node:fs";

const url = process.argv[2] || "";
writeFileSync(
	"src/init/build_config.ts",
	`// Auto-generated by scripts/set-vsx-gallery.mjs — do not edit\nexport const INTERNAL_VSX_GALLERY = ${JSON.stringify(url)};\n`,
);
